// npm run eval:synth [-- <root>] — robustness check on simulator weeks (different network sizes,
// pressures, noise, repair times) generated by Hadent's ml/gen_data.py into data/synth/<week>/
// with labels.json. Scores the rules detector (never trained on anything) and, if the sidecar is
// up, the ML path exactly as the module runs it. Also checks the planner covers every failure.
// Weeks whose seed falls in the model's training range are flagged (in-sample for ML). Eval-only.
import { existsSync, readFileSync, readdirSync } from 'node:fs';
import { join, resolve } from 'node:path';
import { loadFolder } from '../../worker/src/folder';
import { analyze } from '../../core/src/analyze';
import { detectRules } from '../../core/src/detector/rules';
import { seriesKey, tEnd, tsAt, type Grid } from '../../core/src/telemetry';
import type { DetectedEvent } from '../../core/src/types';
import { mlDetect, mlHealth, probsToChunks } from '../../worker/src/ml';
import { parseAnswerKey } from './answerKey';
import { scoreDetection } from './detection';

const root = resolve(process.argv[2] ?? 'data/synth');
// ml/build_dataset.py defaults: weeks seed 1000.. for training (meta.json: 40 weeks)
const TRAIN_SEED_LO = Number(process.env.ML_TRAIN_SEED_LO ?? 1000);
const TRAIN_SEED_HI = Number(process.env.ML_TRAIN_SEED_HI ?? 1039);
if (!existsSync(root)) {
  console.log(`no ${root}; generate with: python ml/gen_data.py --n 4 --out data/synth --seed 9001`);
  process.exit(1);
}
const health = await mlHealth();
console.log(`synthetic eval · ${root} · ML ${health.ok ? health.modelVersion : `unavailable (${health.error})`}`);

type Tot = { hits: number; total: number; fa: number };
const tot: Record<string, Tot> = {};
const add = (k: string, h: number, t: number, f: number) => {
  const x = (tot[k] ??= { hits: 0, total: 0, fa: 0 });
  x.hits += h;
  x.total += t;
  x.fa += f;
};
const iso = (u: number) => new Date(u * 1000).toISOString().slice(5, 16);

function addMl(grid: Grid, chunks: ReturnType<typeof probsToChunks>) {
  for (const c of chunks) {
    const k = seriesKey(c.assetId, c.metric);
    let a = grid.series.get(k);
    if (!a) grid.series.set(k, (a = new Float64Array(grid.n).fill(NaN)));
    const off = Math.round((c.t0 - grid.t0) / grid.stepSec);
    c.values.forEach((v, i) => (a![off + i] = v));
  }
}

for (const name of readdirSync(root).sort()) {
  const dir = join(root, name);
  const lp = join(dir, 'labels.json');
  if (!existsSync(lp) || !existsSync(join(dir, 'telemetry.csv'))) continue;
  const labels = parseAnswerKey(readFileSync(lp, 'utf8'));
  const d = loadFolder(dir);
  const seed = Number(name.match(/(\d+)$/)?.[1] ?? NaN);
  const inSample = seed >= TRAIN_SEED_LO && seed <= TRAIN_SEED_HI;
  const group = inSample ? 'training-range' : 'held-out';
  console.log(`${name} [${group}]: ${d.model.systems.length} systems, ${d.model.facilities.length} facilities, repair ${d.model.repairHoursPumpFailure} h, ${labels.length} labelled events`);

  const detectors: [string, (asOf: number) => DetectedEvent[]][] = [['rules', (asOfUnix) => detectRules(d.model, d.grid, { asOfUnix })]];
  if (health.ok) {
    try {
      addMl(d.grid, probsToChunks(await mlDetect(d.dir, tEnd(d.grid)), { tStart: d.grid.t0, stepSec: d.grid.stepSec, nSteps: d.grid.n }));
      detectors.push(['ml', (asOfUnix) => analyze({ model: d.model, grid: d.grid, asOfUnix, detector: 'ml', skipPlans: true }).events]);
    } catch (e) {
      console.log(`   ML error: ${(e as Error).message}`);
    }
  }
  for (const [tag, detect] of detectors) {
    const t0 = Date.now();
    const s = scoreDetection(d.model, d.grid, labels, { tolSec: 3600, sweepStepSec: 0, detect });
    const ms = Date.now() - t0;
    if (!s.ok) {
      console.log(`   ${tag}: ${s.error}`);
      continue;
    }
    const v = s.value;
    const cats = Object.entries(v.perCategory).map(([c, x]) => `${c.replace('pump_', '').replace('pipeline_', '')} ${x.hits}/${x.total}`).join('  ');
    const h = v.matching.matches.filter((m) => m.detected).length;
    add(`${tag} ${group}`, h, v.matching.matches.length, v.matching.falseAlarms.length);
    const delays = v.matching.matches.filter((m) => m.onsetDeltaSec != null && m.label.category !== 'pump_failure').map((m) => m.onsetDeltaSec! / 3600);
    const med = delays.length ? delays.sort((a, b) => a - b)[Math.floor(delays.length / 2)] : null;
    console.log(`   ${tag.padEnd(5)} ${cats} · FA ${v.matching.falseAlarms.length} · onset Δ (leak/worn) median ${med == null ? '-' : med.toFixed(2) + ' h'} · ${ms} ms`);
    for (const m of v.matching.matches) if (!m.detected) console.log(`      miss ${m.label.id} ${m.label.category} ${m.label.asset} onset ${iso(m.label.onsetUnix)}`);
    for (const e of v.matching.falseAlarms) console.log(`      FA ${e.category} ${e.assetId} ${iso(e.onsetUnix)} → ${e.endUnix ? iso(e.endUnix) : 'ongoing'} conf ${e.confidence.toFixed(2)} (now ${iso(tsAt(d.grid, d.grid.n - 1))})`);
  }
  // planner: every labelled pump failure gets a plan right after onset
  let planned = 0;
  let planMs = 0;
  const fails = labels.filter((x) => x.category === 'pump_failure');
  for (const l of fails) {
    const tp = Date.now();
    const out = analyze({ model: d.model, grid: d.grid, asOfUnix: l.onsetUnix + d.grid.stepSec, detector: 'rules' });
    planMs = Math.max(planMs, Date.now() - tp);
    if (out.plans.some((p) => p.facilities.some((f) => f.facilityId === l.facility))) planned++;
  }
  console.log(`   plans ${planned}/${fails.length} failures planned at onset (max ${planMs} ms)`);
}
console.log('TOTAL');
for (const [k, v] of Object.entries(tot).sort()) console.log(`   ${k.padEnd(20)} ${v.hits}/${v.total} labelled events · ${v.fa} false alarms`);
